package br.com.bancohorizonte; import br.com.bancohorizonte.config.JpaConfig; import br.com.bancohorizonte.http.ApiHandler; import com.sun.net.httpserver.HttpServer; import java.net.*; import java.util.concurrent.*;
public class Application { public static void main(String[] args)throws Exception {HttpServer server=HttpServer.create(new InetSocketAddress(8080),0);server.createContext("/api",new ApiHandler());server.setExecutor(Executors.newVirtualThreadPerTaskExecutor());server.start();Runtime.getRuntime().addShutdownHook(new Thread(()->{server.stop(0);JpaConfig.close();}));System.out.println("Banco Horizonte API em http://localhost:8080");} }
